trx.cutscenes[30]:on_frame(function(cutscene, frame_num)
  trx.log.info("frame " .. frame_num .. " of " .. cutscene.num)
end)

local p = trx.argparse.new({ prog = "weather" })
p:positional("state", { choices = { "snow", "rain", "none" } })
local parsed = p:parse("snow")  -- { state = "snow" }

trx.config.declare({
  key = "mod.water_color_mode",
  kind = "dynamic_enum",
  values = { "tombati", "dos", "custom" },
  default = "custom",
  ui = {
    tab = "graphic_visuals",
    before = "visuals.water_color",
  },
})

trx.console.register({
  name = "greet",
  aliases = { "hello", "hi" },
  args = function(parser)
    parser:positional("who", { help = "who to greet" })
  end,
  run = function(args)
    trx.console.log("hello " .. args.who)
  end,
})

trx.events.on_cutscene_start(function(num)
  if num == 12 then
    trx.cutscenes.set_lara_shadow_bounds({
      min_x = -600, min_y = -777, min_z = -600,
      max_x = 600, max_y = 1, max_z = 600,
    })
  end
end)

trx.events.on_title_start(function()
  trx.log.info("the menu is up")
end)

trx.events.on_flip_effect(62, function(timer, item_num)
  trx.log.info("flipeffect 62 ran with timer " .. timer)
end)

trx.events.on_room_change(function(item, old_room_num, new_room_num)
  trx.log.info(item.object_id .. " moved to room " .. new_room_num)
end)

trx.events.on_finish(function(item)
  trx.log.info(item.object_id .. " finished its run")
end)

trx.events.on_enter_world(function(item)
  trx.log.info(item.object_id .. " entered the world")
end)

trx.events.on_leave_world(function(item)
  trx.log.info(item.object_id .. " left the world")
end)

trx.events.on_hit(function(item, damage)
  trx.log.info(item.object_id .. " lost " .. damage .. " hit points")
end)

trx.events.on_zone_enter(function(zone, item)
  trx.log.info("something entered " .. tostring(zone.name))
end)

trx.events.after_control(function()
  trx.fx.emit_light({
    pos = trx.lara.item.pos,
    radius = 2048,
    color = { r = 0, g = 255, b = 192 },
  })
end)

trx.events.after_control(function()
  trx.fx.emit_fog({
    pos = { x = 32768, y = -1024, z = 45056 },
    radius = 3072,
    density = 64,
    color = { r = 128, g = 160, b = 192 },
  })
end)

trx.events.on_hit(function(item, damage)
  trx.fx.blood({ pos = item.pos, angle = item.rot.y, strength = damage })
end)

trx.locale.declare({
  ["console/cmd/heal/help"] = "Heals Lara back to full health.",
  ["console/cmd/heal/success"] = "Healed Lara back to full health",
})

